:root { font-family: system-ui, sans-serif; }
* { box-sizing: border-box; }
body { display: grid; min-height: 100vh; margin: 0; place-items: center; padding: 20px; color: #0f172a; background: linear-gradient(135deg, #7c3aed, #be185d); }
.quiz { width: min(100%, 580px); padding: clamp(24px, 6vw, 38px); border-radius: 22px; background: #ffffff; box-shadow: 0 24px 70px rgba(15,23,42,.25); }
.quiz > h1 { margin: 0 0 20px; font-size: 1.35rem; }
.progress { height: 8px; overflow: hidden; border-radius: 999px; background: #e2e8f0; }
#progress-bar { display: block; width: 0; height: 100%; background: linear-gradient(90deg, #7c3aed, #db2777); transition: width .3s; }
#question-index { color: #64748b; }
#question-text { min-height: 60px; font-size: 1.25rem; line-height: 1.5; }
.options { display: grid; gap: 10px; }
.options button, #retry { min-height: 48px; padding: 12px 16px; border: 2px solid #e2e8f0; border-radius: 11px; color: #0f172a; background: #ffffff; font: inherit; text-align: left; cursor: pointer; }
.options button.correct { border-color: #15803d; color: #166534; background: #dcfce7; }
.options button.wrong { border-color: #b91c1c; color: #991b1b; background: #fee2e2; }
button:focus-visible { outline: 3px solid #7c3aed; outline-offset: 3px; }
#feedback { min-height: 24px; font-weight: 700; }
#result { text-align: center; }
#score { display: block; color: #6d28d9; font-size: 5rem; }
#retry { text-align: center; }
@media (prefers-reduced-motion: reduce) { #progress-bar { transition: none; } }

const questions = [
  { text: 'Vue 3 的默认响应式能力基于什么实现？', options: ['Object.defineProperty', 'Proxy', 'Observer', 'Getter/Setter'], answer: 1 },
  { text: '哪个 HTTP 状态码表示资源未找到？', options: ['200', '301', '404', '500'], answer: 2 },
  { text: '哪个数组方法不会改变原数组？', options: ['push', 'splice', 'map', 'sort'], answer: 2 },
  { text: '哪个元素最适合作为页面主导航？', options: ['div', 'nav', 'span', 'b'], answer: 1 },
  { text: '为新窗口链接补充哪组 rel 更安全？', options: ['next', 'tag', 'noopener noreferrer', 'author'], answer: 2 }
];
let index = 0;
let correctCount = 0;
const questionSection = document.querySelector('#question');
const resultSection = document.querySelector('#result');
const options = document.querySelector('#options');
const feedback = document.querySelector('#feedback');

function updateProgress(value) {
  document.querySelector('.progress').setAttribute('aria-valuenow', String(value));
  document.querySelector('#progress-bar').style.width = (value / questions.length * 100) + '%';
}

function renderQuestion() {
  if (index >= questions.length) {
    updateProgress(questions.length);
    questionSection.hidden = true;
    resultSection.hidden = false;
    document.querySelector('#score').textContent = String(correctCount * 20);
    document.querySelector('#correct').textContent = '共 ' + questions.length + ' 题，答对 ' + correctCount + ' 题';
    document.querySelector('#retry').focus();
    return;
  }
  const question = questions[index];
  document.querySelector('#question-index').textContent = '第 ' + (index + 1) + ' 题 / 共 ' + questions.length + ' 题';
  document.querySelector('#question-text').textContent = question.text;
  updateProgress(index);
  feedback.textContent = '';
  options.replaceChildren();
  question.options.forEach((text, optionIndex) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = String.fromCharCode(65 + optionIndex) + '. ' + text;
    button.addEventListener('click', () => chooseAnswer(optionIndex, button));
    options.append(button);
  });
}

function chooseAnswer(choice, selectedButton) {
  const question = questions[index];
  const buttons = Array.from(options.querySelectorAll('button'));
  buttons.forEach(button => { button.disabled = true; });
  buttons[question.answer].classList.add('correct');
  if (choice === question.answer) { correctCount++; feedback.textContent = '回答正确'; }
  else { selectedButton.classList.add('wrong'); feedback.textContent = '回答错误，已标出正确答案'; }
  window.setTimeout(() => { index++; renderQuestion(); }, 900);
}

document.querySelector('#retry').addEventListener('click', () => {
  index = 0;
  correctCount = 0;
  resultSection.hidden = true;
  questionSection.hidden = false;
  renderQuestion();
});
renderQuestion();
